// Generated by tooling/unicode-cases/normalization.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [1232984517, 782318021, 2695573957, 721269189, 2879472069, 188189125, 3511513541, 1056057797, 2530136517, 164080069, 863816133, 2549244357, 4193227205, 3345723845, 879182277, 835807685];
const blocks = ["NFC U+070000-U+070FFF", "NFC U+071000-U+071FFF", "NFC U+072000-U+072FFF", "NFC U+073000-U+073FFF", "NFC U+074000-U+074FFF", "NFC U+075000-U+075FFF", "NFC U+076000-U+076FFF", "NFC U+077000-U+077FFF", "NFC U+078000-U+078FFF", "NFC U+079000-U+079FFF", "NFC U+07A000-U+07AFFF", "NFC U+07B000-U+07BFFF", "NFC U+07C000-U+07CFFF", "NFC U+07D000-U+07DFFF", "NFC U+07E000-U+07EFFF", "NFC U+07F000-U+07FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 458752 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
